<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\ValueObject\UserSecondFactorSeedVO;
use Civi\Lughauth\Features\Access\User\Domain\ValueObject\Holder\UserSecondFactorSeedAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserSecondFactorSeedAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserSecondFactorSeedAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that getSecondFactorSeed returns null on a freshly created holder.
         */
        public function testSecondFactorSeedNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithUserSecondFactorSeedAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isSecondFactorSeedAssigned());
            $this->assertNull($holder->getSecondFactorSeed());
        }
}
class ImplWithUserSecondFactorSeedAttributeHolderUnitTest
{
  use UserSecondFactorSeedAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedSecondFactorSeedRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultSecondFactorSeed();
    }}
